def _security_upgrade() -> None:
    op.execute('''
        CREATE FUNCTION app_worker_scope() RETURNS boolean LANGUAGE sql STABLE AS
        $$ SELECT coalesce(current_setting('app.worker_scope', true), '') = 'on' $$;
    ''')
    for table in ("patient_accounts", "patient_link_codes", "notifications"):
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(f'''
            CREATE POLICY tenant_isolation ON {table}
            USING (organisation_id = app_current_org())
            WITH CHECK (organisation_id = app_current_org())
        ''')
    # The delivery worker drains the outbox across organisations. Its scope opens the
    # notifications table only; message bodies were rendered in tenant scope at enqueue.
    op.execute('''
        CREATE POLICY worker_dispatch ON notifications
        USING (app_worker_scope()) WITH CHECK (app_worker_scope())
    ''')
    role = get_settings().app_db_role
    op.execute(f'''
        DO $$
        BEGIN
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{role}') THEN
                GRANT SELECT, INSERT, UPDATE ON organisation_slugs, patient_accounts,
                    patient_link_codes, notifications TO {role};
                GRANT DELETE ON organisation_slugs TO {role};
            END IF;
        END $$;
    ''')


def _slugify(name: str) -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")
    return (slug or "practice")[:50]


def _backfill_slugs() -> None:
    conn = op.get_bind()
    conn.execute(sa.text("SELECT set_config('app.platform_scope', 'on', true)"))
    taken: set[str] = set()
    for org_id, name in conn.execute(sa.text("SELECT id, name FROM organisations ORDER BY created_at")).all():
        base = _slugify(name)
        slug, n = base, 2
        while slug in taken:
            slug, n = f"{base}-{n}", n + 1
        taken.add(slug)
        conn.execute(
            sa.text("INSERT INTO organisation_slugs (slug, organisation_id) VALUES (:s, :o)"),
            {"s": slug, "o": org_id},
        )
    conn.execute(sa.text("SELECT set_config('app.platform_scope', '', true)"))


